List<Integer> xs = new List<Integer>();
System.assert(xs.isEmpty());
xs.add(3);
xs.add(0, 1);
xs.addAll(new List<Integer>{6});
xs.addAll(new Set<Integer>{4, 5});
System.assert(xs.contains(3));
System.assertEquals(1, xs.get(0));
System.assertEquals(1, xs.indexOf(3));
xs.set(1, 2);
System.assertEquals(2, xs.get(1));
System.assertEquals(2, xs.remove(1));
List<Integer> same = new List<Integer>(xs);
System.assert(xs.equals(same));
System.assertEquals(xs.size(), same.size());
List<Integer> cloned0 = xs.deepClone();
List<Integer> cloned1 = xs.deepClone(true);
List<Integer> cloned2 = xs.deepClone(true, true);
List<Integer> cloned3 = xs.deepClone(true, true, true);
System.assertEquals(xs.size(), cloned0.size());
System.assertEquals(xs.size(), cloned1.size());
System.assertEquals(xs.size(), cloned2.size());
System.assertEquals(xs.size(), cloned3.size());
xs.sort();
System.assertEquals(1, xs.get(0));
xs.clear();
System.assert(xs.isEmpty());
Account account = new Account(Id = '001B000001DVM9tIAH', Name = 'Acme');
Contact contact = new Contact(Id = '003B000001DVM9tIAH', LastName = 'Smith');
List<SObject> rel = new List<SObject>();
rel.addToRelationship(account);
rel.addToRelationship(new List<SObject>{contact});
System.assertEquals(2, rel.getAddedToRelationship().size());
rel.markForDelete(contact);
rel.markForDelete(new List<SObject>{account});
System.assertEquals(2, rel.getMarkedForDeletion().size());
List<Account> accounts = new List<Account>{account};
System.assertEquals('Account', accounts.getSObjectType().getDescribe().getName());
Map<String,Integer> counts = new Map<String,Integer>();
System.assert(counts.isEmpty());
System.assertEquals(null, counts.put('a', 1));
System.assertEquals(1, counts.put('a', 2));
System.assert(counts.containsKey('a'));
System.assertEquals(2, counts.get('a'));
System.assert(counts.keySet().contains('a'));
System.assertEquals(1, counts.size());
Map<String,Integer> more = new Map<String,Integer>();
more.put('b', 3);
counts.putAll(more);
Map<String,Integer> clonedCounts = counts.deepClone();
System.assert(counts.equals(clonedCounts));
System.assertEquals(2, counts.remove('a'));
counts.clear();
System.assert(counts.isEmpty());
Map<Id, Account> accountsById = new Map<Id, Account>();
accountsById.put(account.Id, account);
accountsById.putAll(new List<Account>{account});
System.assertEquals('Account', accountsById.getSObjectType().getDescribe().getName());
System.assertEquals('Acme', accountsById.get(account.Id).Name);

